class ListNode:
    def __init__(self, x):
        self.val = x
        self.next = None

class Solution:
    def hasCycle(self, head: ListNode) -> bool:
        if not head or not head.next:
            return False

        slow = head
        fast = head.next

        while slow != fast:
            if not fast or not fast.next:
                return False
            slow = slow.next
            fast = fast.next.next

        return True

def create_linked_list(arr, pos):
    if not arr:
        return None

    # Create the linked list
    head = ListNode(arr[0])
    current = head
    for value in arr[1:]:
        current.next = ListNode(value)
        current = current.next

    # Create the cycle if pos is valid
    if pos >= 0:
        cycle_node = head
        for _ in range(pos):
            cycle_node = cycle_node.next
        current.next = cycle_node

    return head

